'use strict';
window.TemplateMail={mount(host,callbacks){
const box=document.createElement('details');box.innerHTML=`<summary>Тестовая отправка email</summary><p data-mail="config">Проверка SMTP…</p><label>Тестовый получатель<select data-mail="recipient"><option value="">Не настроен</option></select></label><p>Отправляется текущий текст редактора с данными примера персонализации и пометкой [ТЕСТ]. Письмо получит только выбранный адрес. Отписка в тесте отключена.</p><button type="button" class="outline" data-mail="send" disabled>Отправить тестовое письмо</button> <button type="button" class="outline" data-mail="new">Новый тест</button> <button type="button" class="outline" data-mail="refresh">Обновить статус</button><p data-mail="message" role="status"></p><div data-mail="history" class="table-scroll"></div>`;host.append(box);
const $=id=>box.querySelector('[data-mail="'+id+'"]');let ready=false,busy=false,attempt=null;
try{attempt=JSON.parse(sessionStorage.getItem('template-test-mail-attempt')||'null');}catch{}
const labels={pending:'Результат пока не подтверждён',accepted:'Принято SMTP',failed:'Ошибка',unknown:'Результат неизвестен'};
function show(row){$('message').textContent=(labels[row.state]||row.state)+'. '+(row.detail||'Проверьте почту и журнал провайдера. Повторная отправка автоматически не выполняется.');}
async function refresh(){try{const r=await api('/api/templates/test-mail');ready=r.configured;$('config').textContent=r.configured?'SMTP настроен. Отправитель: '+r.sender+'. '+r.note:'SMTP не настроен. Нужны параметры: '+r.missing.join(', ')+'. Пароль задаётся в окружении сервера.';const previous=$('recipient').value;$('recipient').replaceChildren();for(const address of r.recipients)$('recipient').add(new Option(address,address));if(r.recipients.includes(previous))$('recipient').value=previous;if(!r.recipients.length)$('recipient').add(new Option('Нет тестовых адресов',''));$('send').disabled=!ready||busy;
 $('history').replaceChildren();if(r.history.length){const table=document.createElement('table');const title=document.createElement('caption');title.textContent='Последние тестовые отправки';table.append(title);for(const row of r.history){const tr=document.createElement('tr');for(const value of [new Date(row.created_at).toLocaleString('ru-RU'),row.recipient,row.subject,labels[row.state]||row.state]){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.append(tr);if(attempt?.token===row.token)show(row);}$('history').append(table);}
}catch(e){$('config').textContent=e.message;ready=false;$('send').disabled=true;}}
$('send').onclick=async()=>{if(busy||!ready)return;const s=callbacks.state();const payload={recipient:$('recipient').value,subject:s.subject,preheader:s.preheader,html:s.html,values:callbacks.values()};const json=JSON.stringify(payload);if(!attempt||attempt.json!==json){attempt={json,token:crypto.randomUUID()};}try{sessionStorage.setItem('template-test-mail-attempt',JSON.stringify(attempt));}catch{$('message').textContent='Не удалось сохранить идентификатор теста в этой вкладке. Освободите хранилище браузера перед отправкой.';return;}
busy=true;$('send').disabled=true;$('new').disabled=true;$('recipient').disabled=true;$('message').textContent='Передача тестового письма SMTP-серверу…';try{const row=await api('/api/templates/test-mail',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,token:attempt.token})});show(row);await refresh();}catch(e){$('message').textContent=e.message+' Если соединение оборвалось, обновите статус перед новым тестом. Повтор с тем же содержимым использует прежний идентификатор.';}finally{busy=false;$('new').disabled=false;$('recipient').disabled=false;$('send').disabled=!ready;}};
$('new').onclick=()=>{if(busy)return;attempt=null;try{sessionStorage.removeItem('template-test-mail-attempt');}catch{}$('message').textContent='Создан новый тест. Следующее нажатие отправит ещё одно письмо на выбранный адрес.';};$('refresh').onclick=refresh;refresh();
}};
